#include <iostream>
#include <vector>
#include <cstdint>

int64_t count_digits_total(int64_t num) {
    num = (num < 0) ? -num : num;
    int64_t count = 0;
    while (num != 0) {
        ++count;
        num /= 10;
    }
    return count;
}

int64_t build_ones_sequence(int64_t length) {
    int64_t result = 0;
    for (int i = 0; i < length; ++i)
        result = result * 10 + 1;
    return result;
}

int64_t helper2(int64_t num) {
    if (num == 0) return 0;
    num = (num < 0) ? -num : num;
    int64_t d = count_digits_total(num);
    return d + helper2(num - build_ones_sequence(d));
}

int64_t helper(int64_t n, int64_t s, int64_t a, int64_t m, std::vector<int>& state) {
    if (a >= m) return m;
    if (n == 0) return a;
    if (n < 0) { n = -n; s = -s; }
    int64_t d = count_digits_total(n);
    int64_t ones_d = build_ones_sequence(d);
    int64_t res1 = m, res2 = m;

    if (0 <= state[d] * s && -10 < state[d] && state[d] < 10) {
        state[d] += s;
        res1 = helper(n - ones_d, s, a + d, m, state);
        state[d] -= s;
    }
    if (0 <= state[d + 1] * s && -10 < state[d + 1] && state[d + 1] < 10) {
        state[d + 1] += s;
        res2 = helper(n - 10 * ones_d - 1, s, a + d + 1, res1, state);
        state[d + 1] -= s;
    }
    return res1 < res2 ? res1 : res2;
}

int main() {
    int64_t n;
    std::cin >> n;
    std::vector<int> state(20, 0);
    std::cout << helper(n, 1, 0, helper2(n), state) << std::endl;
    return 0;
}
